-- Synthetic fixtures only; run after the sales migration. All changes roll back.
begin;
do $$
declare owner uuid=gen_random_uuid(); member uuid=gen_random_uuid(); outsider uuid=gen_random_uuid();
 ring uuid=gen_random_uuid(); other_ring uuid=gen_random_uuid(); a uuid=gen_random_uuid(); b uuid=gen_random_uuid();
 foreign_animal uuid=gen_random_uuid(); sale uuid; second uuid; invitation uuid; n integer;
begin
 insert into auth.users(id,email,email_confirmed_at) values(owner,owner||'@example.invalid',now()),(member,member||'@example.invalid',now()),(outsider,outsider||'@example.invalid',now());
 insert into public.users(id,auth_user_id,username,email) values(owner::text,owner,owner::text,owner||'@example.invalid'),(outsider::text,outsider,outsider::text,outsider||'@example.invalid');
 insert into public.farms(id,name,owner_id) values(ring,'Sales test',owner::text),(other_ring,'Other family',outsider::text);
 insert into public.animals(id,ring_id,name,species,sex,status) values(a,ring,'Listed animal','rabbit','M','active'),(b,ring,'Second animal','rabbit','F','active'),(foreign_animal,other_ring,'Other family animal','rabbit','F','active');
 insert into breeder_private.invitations(owner_id,email,member_user_id,accepted_at) values(owner::text,member||'@example.invalid',member,now()) returning id into invitation;
 perform set_config('request.jwt.claim.sub',owner::text,true); execute 'set local role authenticated';
 insert into public.animal_sales(animal_id,ring_id,animal_name,asking_cents) values(a,ring,'Cannot forge snapshot',10000) returning id into sale;
 if (select animal_name from public.animal_sales where id=sale)<>'Listed animal' then raise exception 'Animal snapshot was not verified'; end if;
 if (select status from public.animals where id=a)<>'active' then raise exception 'Listing changed herd status'; end if;
 begin insert into public.animal_sales(animal_id,ring_id,animal_name) values(a,ring,'Duplicate'); raise exception 'Duplicate listing allowed'; exception when unique_violation then null; end;
 begin insert into public.animal_sales(animal_id,ring_id,animal_name) values(foreign_animal,ring,'Stolen'); raise exception 'Cross-family animal listing allowed'; exception when raise_exception then if sqlerrm='Cross-family animal listing allowed' then raise; end if; end;
 insert into public.animal_sale_payments(sale_id,kind,amount_cents,created_by) values(sale,'deposit',2500,outsider);
 if (select created_by from public.animal_sale_payments where sale_id=sale)<>owner then raise exception 'Payment actor forged'; end if;
 begin insert into public.animal_sale_payments(sale_id,kind,amount_cents) values(sale,'payment',8000); raise exception 'Overpayment allowed'; exception when raise_exception then if sqlerrm='Overpayment allowed' then raise; end if; end;
 begin update public.animal_sales set sale_cents=1000 where id=sale; raise exception 'Price below paid allowed'; exception when raise_exception then if sqlerrm='Price below paid allowed' then raise; end if; end;
 begin update public.animal_sales set status='cancelled' where id=sale; raise exception 'Paid cancellation allowed'; exception when raise_exception then if sqlerrm='Paid cancellation allowed' then raise; end if; end;
 update public.animal_sales set status='reserved',buyer_name='Buyer',buyer_email='buyer@example.invalid',buyer_address='Private address',sale_cents=9000 where id=sale;
 insert into public.animal_sale_payments(sale_id,kind,amount_cents,method) values(sale,'payment',6500,'Cash');
 insert into public.animal_sale_payments(sale_id,kind,amount_cents) values(sale,'refund',1000);
 begin insert into public.animal_sale_payments(sale_id,kind,amount_cents) values(sale,'refund',9000); raise exception 'Excess refund allowed'; exception when raise_exception then if sqlerrm='Excess refund allowed' then raise; end if; end;
 begin update public.animals set status='sold' where id=a; raise exception 'Open listing bypassed'; exception when raise_exception then if sqlerrm='Open listing bypassed' then raise; end if; end;
 update public.animal_sales set status='sold',sale_date=current_date where id=sale;
 if (select status from public.animals where id=a)<>'sold' then raise exception 'Animal not marked sold'; end if;
 if (select sum(case when kind='refund' then -amount_cents else amount_cents end) from public.animal_sale_payments where sale_id=sale)<>8000 then raise exception 'Payment/refund arithmetic incorrect'; end if;
 begin update public.animal_sale_payments set amount_cents=1 where sale_id=sale; raise exception 'Payment history editable'; exception when insufficient_privilege then null; end;
 begin delete from public.animal_sale_payments where sale_id=sale; raise exception 'Payment history deletable'; exception when insufficient_privilege then null; end;
 begin insert into public.animal_sale_history(sale_id,event,details,created_by) values(sale,'forged','{}',owner); raise exception 'Audit forgery allowed'; exception when insufficient_privilege then null; end;
 begin update public.animal_sales set ring_id=other_ring where id=sale; raise exception 'Sale identity changed'; exception when raise_exception then if sqlerrm='Sale identity changed' then raise; end if; end;
 insert into public.animal_sales(animal_id,ring_id,animal_name,asking_cents) values(b,ring,'',5000) returning id into second;
 update public.animal_sales set status='cancelled' where id=second;
 insert into public.animal_sales(animal_id,ring_id,animal_name,asking_cents) values(b,ring,'',5500);
 if not exists(select 1 from public.animal_sale_history where sale_id=sale and event='refund') then raise exception 'Refund audit missing'; end if;
 perform set_config('request.jwt.claim.sub',member::text,true);
 if not exists(select 1 from public.animal_sales where id=sale and buyer_email='buyer@example.invalid') then raise exception 'Accepted family member cannot see sales'; end if;
 update public.animal_sales set notes='Family edit' where id=sale;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 if exists(select 1 from public.animal_sales where ring_id=ring) or exists(select 1 from public.animal_sale_payments where sale_id=sale) or exists(select 1 from public.animal_sale_history where sale_id=sale) then raise exception 'Private sales leaked across families'; end if;
 begin insert into public.animal_sale_payments(sale_id,kind,amount_cents) values(sale,'payment',1); raise exception 'Outsider payment accepted'; exception when raise_exception then if sqlerrm='Outsider payment accepted' then raise; end if; end;
 execute 'reset role'; update breeder_private.invitations set revoked_at=now() where id=invitation;
 execute 'set local role authenticated'; perform set_config('request.jwt.claim.sub',member::text,true);
 if exists(select 1 from public.animal_sales where ring_id=ring) then raise exception 'Revoked member retained access'; end if;
 execute 'reset role';
 raise notice 'Sales dashboard database assertions passed';
end $$;
rollback;
